function validate(input) {
  const [{ Players = [], Matches = [] }] = input;
  const group = new Map();
  for (const row of Players) {
    if (row.some((v) => v === null)) return 'Players rows may not contain null.';
    if (group.has(row[0])) return `player_id ${row[0]} appears twice in Players.`;
    group.set(row[0], row[1]);
  }
  const ids = new Set();
  for (const row of Matches) {
    if (row.some((v) => v === null)) return 'Matches rows may not contain null.';
    const [id, a, b, sa, sb] = row;
    if (ids.has(id)) return `match_id ${id} appears twice in Matches.`;
    ids.add(id);
    if (!group.has(a) || !group.has(b)) return `Match ${id} names a player missing from Players.`;
    if (a === b) return `Match ${id} pits player ${a} against themselves.`;
    if (group.get(a) !== group.get(b)) return `Match ${id} pairs players from different groups.`;
    if (sa < 0 || sb < 0) return `Match ${id} has a negative score.`;
  }
  return null;
}

