function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const Players = [], Matches = [];
  if (small) {
    const pool = [10, 15, 20, 25, 30, 35, 40, 45];
    for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    const count = Math.floor(rand() * 9), groups = 1 + Math.floor(rand() * 3);
    for (const id of pool.slice(0, count)) Players.push([id, 1 + Math.floor(rand() * groups)]);
  } else {
    const ids = Array.from({ length: 1000 }, (_, i) => i + 1);
    for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
    for (const id of ids) Players.push([id, 1 + Math.floor(rand() * 60)]);
  }
  // Matches only pair players of the same group; small scores make tied totals common.
  const members = new Map();
  for (const [id, g] of Players) { if (!members.has(g)) members.set(g, []); members.get(g).push(id); }
  const playable = [...members.values()].filter((list) => list.length >= 2);
  const matches = playable.length === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  for (let id = 1; id <= matches; id++) {
    const list = pick(playable);
    const a = pick(list);
    let b = pick(list);
    while (b === a) b = pick(list);
    const top = small ? 4 : 11;
    Matches.push([id, a, b, Math.floor(rand() * top), Math.floor(rand() * top)]);
  }
  return [{ Players, Matches }];
}
